import AppKit
import CryptoKit
import Foundation
import OpenBurnBarCore

// MARK: - Release metadata

/// One release entry from `latest-macos.json`, the direct-download update feed
/// published by `release.yml` and generated by `scripts/generate-macos-appcast.mjs`.
///
/// Trust model: the feed JSON is fetched over HTTPS from the GitHub releases
/// CDN but is **not** independently authenticated — anyone who can tamper with
/// the transport or the release assets can rewrite it. The authenticated
/// object is the DMG itself: the release pipeline runs Sparkle's
/// `sign_update`, which produces an Ed25519 signature over the **DMG file
/// bytes**, and embeds it in the feed as `sparkleEdSignature`.
/// `DirectDownloadArtifactVerifier` re-verifies that signature against the
/// `SUPublicEDKey` pinned in Info.plist after downloading and before the file
/// is ever opened.
struct DirectDownloadRelease: Equatable, Sendable {
    let version: String
    let build: String
    let downloadUrl: URL
    let appcastUrl: URL?
    let length: Int
    let sha256: String
    let sparkleEdSignature: String?
    /// Security-critical release flag (emitted by `generate-macos-appcast.mjs
    /// --critical 1`). Critical releases re-prompt even after "Later".
    let critical: Bool
}

extension DirectDownloadRelease: Decodable {
    private enum CodingKeys: String, CodingKey {
        case version
        case build
        case downloadUrl
        case appcastUrl
        case length
        case sha256
        case sparkleEdSignature
        case critical
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        version = try container.decode(String.self, forKey: .version)
        build = try container.decode(String.self, forKey: .build)
        downloadUrl = try container.decode(URL.self, forKey: .downloadUrl)
        appcastUrl = try container.decodeIfPresent(URL.self, forKey: .appcastUrl)
        length = try container.decode(Int.self, forKey: .length)
        sha256 = try container.decode(String.self, forKey: .sha256)
        sparkleEdSignature = try container.decodeIfPresent(String.self, forKey: .sparkleEdSignature)
        critical = try container.decodeIfPresent(Bool.self, forKey: .critical) ?? false
    }
}

extension DirectDownloadRelease {
    /// Numeric `CFBundleVersion` comparison first; falls back to a numeric
    /// `CFBundleShortVersionString` comparison when builds are equal or
    /// non-numeric (so `1.10.0` > `1.9.0`).
    func isNewer(thanBuild currentBuild: String, currentVersion: String) -> Bool {
        if let remote = Int(build), let local = Int(currentBuild), remote != local {
            return remote > local
        }
        return version.compare(currentVersion, options: .numeric) == .orderedDescending
    }

    var isNewerThanCurrentBundle: Bool {
        let info = Bundle.main.infoDictionary ?? [:]
        return isNewer(
            thanBuild: info["CFBundleVersion"] as? String ?? "0",
            currentVersion: info["CFBundleShortVersionString"] as? String ?? "0"
        )
    }

    /// Shape-only sanity filter for feed metadata: HTTPS scheme, download host
    /// pinned to the feed host, 64-hex digest shape, plausible length, and
    /// signature presence.
    ///
    /// This is **not** a trust decision — it cannot detect a forged feed or a
    /// swapped artifact. Trust is established exclusively by
    /// `DirectDownloadArtifactVerifier`, which checks the SHA-256 digest and
    /// verifies the Ed25519 signature over the downloaded DMG bytes against
    /// the pinned `SUPublicEDKey` before the file is opened. (Renamed from
    /// `isTrustedDirectDownloadMetadata`, which implied cryptographic trust it
    /// never provided.)
    func hasWellFormedDownloadMetadata(from feedURL: URL) -> Bool {
        guard downloadUrl.scheme == "https" else { return false }
        guard appcastUrl?.scheme != "http" else { return false }
        guard length > 0 else { return false }
        guard sha256.range(of: "^[A-Fa-f0-9]{64}$", options: .regularExpression) != nil else {
            return false
        }
        guard let sparkleEdSignature,
              !sparkleEdSignature.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return false
        }

        guard let feedHost = feedURL.host?.lowercased(),
              let downloadHost = downloadUrl.host?.lowercased() else {
            return false
        }
        return feedHost == downloadHost
    }
}

// MARK: - Artifact verification

enum DirectDownloadVerificationError: Error, Equatable {
    case missingPublicKey
    case malformedPublicKey
    case missingSignature
    case malformedSignature
    case lengthMismatch(expected: Int, actual: Int)
    case sha256Mismatch(expected: String, actual: String)
    case signatureInvalid
    case unreadableArtifact(String)
}

extension DirectDownloadVerificationError: LocalizedError {
    var errorDescription: String? {
        switch self {
        case .missingPublicKey:
            return "The app bundle does not contain an update signing key (SUPublicEDKey)."
        case .malformedPublicKey:
            return "The bundled update signing key (SUPublicEDKey) is not a valid Ed25519 public key."
        case .missingSignature:
            return "The update feed did not include an Ed25519 signature for the download."
        case .malformedSignature:
            return "The update's Ed25519 signature is not valid base64 or has the wrong size."
        case let .lengthMismatch(expected, actual):
            return "The downloaded file is \(actual) bytes but the feed advertised \(expected) bytes."
        case let .sha256Mismatch(expected, actual):
            return "The downloaded file's SHA-256 digest (\(actual)) does not match the feed (\(expected))."
        case .signatureInvalid:
            return "The downloaded file's Ed25519 signature does not verify against the key this app shipped with."
        case let .unreadableArtifact(reason):
            return "The downloaded file could not be read for verification: \(reason)"
        }
    }
}

/// Verifies a downloaded update artifact against the feed metadata and the
/// Ed25519 public key pinned in Info.plist (`SUPublicEDKey`).
///
/// What is verified, in order, all of which must pass:
/// 1. Exact byte length advertised by the feed.
/// 2. SHA-256 digest of the file bytes equals the feed's `sha256`.
/// 3. Ed25519 signature (`sparkleEdSignature`, produced by Sparkle's
///    `sign_update` over the file bytes) verifies against `SUPublicEDKey`.
struct DirectDownloadArtifactVerifier: Sendable {
    /// Base64 of the raw 32-byte Ed25519 public key (Sparkle `SUPublicEDKey`).
    let publicKeyBase64: String

    static let publicKeyInfoPlistKey = "SUPublicEDKey"

    /// Reads the pinned `SUPublicEDKey` from the bundle, or `nil` when absent.
    /// Callers must fail closed (never offer or open an update) when this is
    /// `nil`.
    static func bundledPublicKeyBase64(in bundle: Bundle = .main) -> String? {
        guard let value = bundle.object(forInfoDictionaryKey: publicKeyInfoPlistKey) as? String else {
            return nil
        }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    func verify(
        fileAt fileURL: URL,
        expectedLength: Int,
        expectedSHA256: String,
        edSignatureBase64: String?
    ) throws {
        let data: Data
        do {
            data = try Data(contentsOf: fileURL, options: [.mappedIfSafe])
        } catch {
            throw DirectDownloadVerificationError.unreadableArtifact(String(describing: error))
        }
        try verify(
            data: data,
            expectedLength: expectedLength,
            expectedSHA256: expectedSHA256,
            edSignatureBase64: edSignatureBase64
        )
    }

    func verify(
        data: Data,
        expectedLength: Int,
        expectedSHA256: String,
        edSignatureBase64: String?
    ) throws {
        if expectedLength > 0, data.count != expectedLength {
            throw DirectDownloadVerificationError.lengthMismatch(expected: expectedLength, actual: data.count)
        }

        let digest = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
        guard digest == expectedSHA256.lowercased() else {
            throw DirectDownloadVerificationError.sha256Mismatch(
                expected: expectedSHA256.lowercased(),
                actual: digest
            )
        }

        guard let signatureBase64 = edSignatureBase64?.trimmingCharacters(in: .whitespacesAndNewlines),
              !signatureBase64.isEmpty else {
            throw DirectDownloadVerificationError.missingSignature
        }
        guard let signature = Data(base64Encoded: signatureBase64), signature.count == 64 else {
            throw DirectDownloadVerificationError.malformedSignature
        }

        let keyBase64 = publicKeyBase64.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !keyBase64.isEmpty else {
            throw DirectDownloadVerificationError.missingPublicKey
        }
        guard let keyData = Data(base64Encoded: keyBase64), keyData.count == 32,
              let publicKey = try? Curve25519.Signing.PublicKey(rawRepresentation: keyData) else {
            throw DirectDownloadVerificationError.malformedPublicKey
        }

        guard publicKey.isValidSignature(signature, for: data) else {
            throw DirectDownloadVerificationError.signatureInvalid
        }
    }
}

// MARK: - Prompt state machine

/// Decides whether an available release should prompt the user.
///
/// Deferral state is **in-memory only** — by design nothing is persisted, so a
/// "Later" can never permanently mute a build (the old checker persisted the
/// prompted build to UserDefaults *before* the user even responded, which
/// silenced security releases forever after a single "Later"). A "Later" now
/// defers until the next app launch or until `deferralInterval` (24h) elapses
/// within the same process, whichever comes first. Security-critical releases
/// (`critical: true` in the feed) re-prompt regardless of deferral.
struct DirectDownloadUpdatePromptPolicy: Sendable {
    struct Deferral: Equatable, Sendable {
        var build: String
        var deferredAt: Date
    }

    let deferralInterval: TimeInterval
    private(set) var deferral: Deferral?

    init(deferralInterval: TimeInterval = 24 * 60 * 60) {
        self.deferralInterval = deferralInterval
    }

    func shouldPrompt(for release: DirectDownloadRelease, at now: Date = Date()) -> Bool {
        if release.critical { return true }
        guard let deferral, deferral.build == release.build else { return true }
        return now.timeIntervalSince(deferral.deferredAt) >= deferralInterval
    }

    mutating func noteDeferred(build: String, at now: Date = Date()) {
        deferral = Deferral(build: build, deferredAt: now)
    }
}

// MARK: - Update checker

#if !DISTRIBUTION_MAS
/// Direct-download update channel for the notarized DMG distribution.
///
/// Flow: fetch `latest-macos.json` → user consents via prompt → download the
/// DMG to a temp path in-app → verify sha256 + Ed25519 signature over the
/// downloaded bytes against the pinned `SUPublicEDKey` → only then open the
/// verified local file. A failed verification deletes the download and shows a
/// security-honest error; the unverified file is never opened.
///
/// Checks run 12s after launch and then every 24 hours, plus on demand via
/// `checkForUpdatesNow()` ("Check for Updates..." in the status-item menu).
@MainActor
final class DirectDownloadUpdateChecker {
    static let shared = DirectDownloadUpdateChecker()

    private static let feedURLKey = "OpenBurnBarDirectUpdateFeedURL"
    /// Pre-verification defaults key. The legacy checker wrote it before
    /// `runModal`, permanently muting a build after one "Later". It is removed
    /// on start so previously muted machines are prompted again.
    private static let legacyPromptedBuildKey = "OpenBurnBarLastPromptedDirectUpdateBuild"
    private static let defaultFeedURL =
        URL(string: "https://github.com/Imagine-That-Ai/BurnBar/releases/latest/download/latest-macos.json")!
    private static let releasesPageURL =
        URL(string: "https://github.com/Imagine-That-Ai/BurnBar/releases/latest")!
    private static let recheckInterval: TimeInterval = 24 * 60 * 60

    private var hasStartedAutomaticChecks = false
    private var launchCheckTask: Task<Void, Never>?
    private var recheckTimer: Timer?
    private var promptPolicy = DirectDownloadUpdatePromptPolicy()
    /// True while a prompt is on screen or a download/verification is running.
    private var isBusy = false

    private init() {}

    func startAutomaticChecks() {
        guard !hasStartedAutomaticChecks,
              !OpenBurnBarRuntime.isRunningTests,
              ProcessInfo.processInfo.environment["OPENBURNBAR_DISABLE_UPDATE_CHECK"] != "1" else {
            return
        }

        let isInstalledApp = Bundle.main.bundleURL.standardizedFileURL.path == "/Applications/OpenBurnBar.app"
        let isExplicitlyEnabled = ProcessInfo.processInfo.environment["OPENBURNBAR_ENABLE_UPDATE_CHECK"] == "1"
        guard isInstalledApp || isExplicitlyEnabled else { return }
        hasStartedAutomaticChecks = true

        UserDefaults.standard.removeObject(forKey: Self.legacyPromptedBuildKey)

        launchCheckTask = Task { [weak self] in
            try? await Task.sleep(nanoseconds: 12_000_000_000)
            await self?.runCheck(userInitiated: false)
        }

        let timer = Timer.scheduledTimer(withTimeInterval: Self.recheckInterval, repeats: true) { _ in
            Task { @MainActor in
                await DirectDownloadUpdateChecker.shared.runCheck(userInitiated: false)
            }
        }
        timer.tolerance = Self.recheckInterval / 24
        recheckTimer = timer
    }

    /// User-initiated "Check for Updates..." — bypasses the "Later" deferral
    /// and surfaces the up-to-date / unreachable states that automatic checks
    /// keep silent.
    func checkForUpdatesNow() {
        guard !OpenBurnBarRuntime.isRunningTests else { return }
        Task { [weak self] in
            await self?.runCheck(userInitiated: true)
        }
    }

    private func configuredFeedURL() -> URL {
        if let value = Bundle.main.object(forInfoDictionaryKey: Self.feedURLKey) as? String,
           let url = URL(string: value) {
            return url
        }
        return Self.defaultFeedURL
    }

    private func runCheck(userInitiated: Bool) async {
        guard !isBusy else { return }
        let feedURL = configuredFeedURL()
        do {
            let release = try await Self.fetchLatestRelease(from: feedURL)
            handleFetchedRelease(release, feedURL: feedURL, userInitiated: userInitiated)
        } catch {
            NSLog("OpenBurnBar direct update check failed: %@", String(describing: error))
            if userInitiated {
                presentManualCheckUnavailableAlert()
            }
        }
    }

    private nonisolated static func fetchLatestRelease(from url: URL) async throws -> DirectDownloadRelease {
        guard url.scheme == "https" else {
            throw URLError(.appTransportSecurityRequiresSecureConnection)
        }

        let (data, response) = try await URLSession.shared.data(from: url)
        guard let httpResponse = response as? HTTPURLResponse,
              (200..<300).contains(httpResponse.statusCode) else {
            throw URLError(.badServerResponse)
        }
        return try JSONDecoder().decode(DirectDownloadRelease.self, from: data)
    }

    private func handleFetchedRelease(_ release: DirectDownloadRelease, feedURL: URL, userInitiated: Bool) {
        guard release.isNewerThanCurrentBundle else {
            if userInitiated { presentUpToDateAlert() }
            return
        }
        guard release.hasWellFormedDownloadMetadata(from: feedURL) else {
            NSLog(
                "SECURITY: OpenBurnBar update feed entry for build %@ is malformed (bad scheme, host mismatch, or missing digest/signature); refusing to offer it.",
                release.build
            )
            if userInitiated { presentManualCheckUnavailableAlert() }
            return
        }
        guard DirectDownloadArtifactVerifier.bundledPublicKeyBase64() != nil else {
            // Fail closed: without the pinned key we cannot verify anything we
            // download, so we never offer the update at all.
            NSLog("SECURITY: SUPublicEDKey missing from Info.plist; refusing to offer update %@.", release.version)
            if userInitiated { presentManualCheckUnavailableAlert() }
            return
        }
        guard userInitiated || promptPolicy.shouldPrompt(for: release, at: Date()) else { return }
        presentUpdatePrompt(release)
    }

    private func presentUpdatePrompt(_ release: DirectDownloadRelease) {
        guard !isBusy else { return }
        isBusy = true

        let alert = NSAlert()
        if release.critical {
            alert.messageText = "OpenBurnBar \(release.version) is a critical security update"
            alert.informativeText = "This release fixes a security issue. OpenBurnBar will download the update and verify its cryptographic signature before opening it."
            alert.alertStyle = .critical
        } else {
            alert.messageText = "OpenBurnBar \(release.version) is available"
            alert.informativeText = "A newer notarized build is ready. OpenBurnBar will download the update and verify its cryptographic signature before opening it."
            alert.alertStyle = .informational
        }
        alert.addButton(withTitle: "Download Update")
        alert.addButton(withTitle: "Later")

        let response = alert.runModal()
        // Record the decision only AFTER the user responds. (The legacy
        // checker persisted before runModal, which muted the build forever.)
        promptPolicy.noteDeferred(build: release.build, at: Date())
        if response == .alertFirstButtonReturn {
            downloadVerifyAndOpen(release)
        } else {
            isBusy = false
        }
    }

    private func downloadVerifyAndOpen(_ release: DirectDownloadRelease) {
        guard let publicKeyBase64 = DirectDownloadArtifactVerifier.bundledPublicKeyBase64() else {
            NSLog("SECURITY: SUPublicEDKey missing from Info.plist; refusing to download update %@.", release.version)
            isBusy = false
            return
        }
        let verifier = DirectDownloadArtifactVerifier(publicKeyBase64: publicKeyBase64)

        Task { [weak self] in
            let outcome = await Self.downloadAndVerify(release: release, verifier: verifier)
            guard let self else { return }
            self.isBusy = false
            switch outcome {
            case let .success(fileURL):
                NSLog(
                    "OpenBurnBar update %@ downloaded and verified (sha256 + Ed25519 against SUPublicEDKey); opening %@",
                    release.version,
                    fileURL.path
                )
                NSWorkspace.shared.open(fileURL)
            case let .failure(error):
                NSLog(
                    "SECURITY: OpenBurnBar update verification FAILED for %@ — deleted the download, refusing to open it. Error: %@",
                    release.downloadUrl.absoluteString,
                    String(describing: error)
                )
                self.presentVerificationFailureAlert(release: release, error: error)
            }
        }
    }

    /// Downloads the DMG to a temp path and verifies length + SHA-256 +
    /// Ed25519 signature over its bytes. On any failure the downloaded file is
    /// deleted before returning.
    private nonisolated static func downloadAndVerify(
        release: DirectDownloadRelease,
        verifier: DirectDownloadArtifactVerifier
    ) async -> Result<URL, Error> {
        let fileManager = FileManager.default
        let destinationDir = fileManager.temporaryDirectory
            .appendingPathComponent("OpenBurnBarUpdates", isDirectory: true)
            .appendingPathComponent(release.build, isDirectory: true)
        let fileName = release.downloadUrl.lastPathComponent
        let destination = destinationDir.appendingPathComponent(
            fileName.hasSuffix(".dmg") ? fileName : "OpenBurnBar-\(release.version).dmg"
        )

        do {
            let (downloadedURL, response) = try await URLSession.shared.download(from: release.downloadUrl)
            guard let httpResponse = response as? HTTPURLResponse,
                  (200..<300).contains(httpResponse.statusCode) else {
                try? fileManager.removeItem(at: downloadedURL)
                return .failure(URLError(.badServerResponse))
            }
            try fileManager.createDirectory(at: destinationDir, withIntermediateDirectories: true)
            try? fileManager.removeItem(at: destination)
            try fileManager.moveItem(at: downloadedURL, to: destination)
            try verifier.verify(
                fileAt: destination,
                expectedLength: release.length,
                expectedSHA256: release.sha256,
                edSignatureBase64: release.sparkleEdSignature
            )
            return .success(destination)
        } catch {
            try? fileManager.removeItem(at: destination)
            return .failure(error)
        }
    }

    // MARK: Alerts

    private func presentVerificationFailureAlert(release: DirectDownloadRelease, error: Error) {
        let alert = NSAlert()
        alert.alertStyle = .critical
        alert.messageText = "Update verification failed"
        alert.informativeText = """
        OpenBurnBar downloaded version \(release.version) but could not verify it against the signing key this app shipped with. The downloaded file has been deleted and was not opened.

        \(error.localizedDescription)

        This can indicate a corrupted download or a tampered update. You can download OpenBurnBar manually from the official releases page.
        """
        alert.addButton(withTitle: "Open Releases Page")
        alert.addButton(withTitle: "OK")
        if alert.runModal() == .alertFirstButtonReturn {
            NSWorkspace.shared.open(Self.releasesPageURL)
        }
    }

    private func presentUpToDateAlert() {
        let info = Bundle.main.infoDictionary ?? [:]
        let version = info["CFBundleShortVersionString"] as? String ?? "?"
        let alert = NSAlert()
        alert.alertStyle = .informational
        alert.messageText = "You're up to date"
        alert.informativeText = "OpenBurnBar \(version) is the newest version available."
        alert.addButton(withTitle: "OK")
        alert.runModal()
    }

    private func presentManualCheckUnavailableAlert() {
        let alert = NSAlert()
        alert.alertStyle = .informational
        alert.messageText = "Could not check for updates"
        alert.informativeText = "The update feed could not be reached or did not contain a verifiable release. Please try again later, or visit the releases page."
        alert.addButton(withTitle: "Open Releases Page")
        alert.addButton(withTitle: "OK")
        if alert.runModal() == .alertFirstButtonReturn {
            NSWorkspace.shared.open(Self.releasesPageURL)
        }
    }
}
#endif
